shellCommands.command:
/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'

for (let request = 1; request <= 2; request++) {
  const start = Date.now()
  const response = await fetch('http://localhost:3101/')
  assert.equal(response.status, 200)
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let html = ''
  let firstChunkAt = 0
  while (true) {
    const { value, done } = await reader.read()
    if (done) break
    if ("'!firstChunkAt) firstChunkAt = Date.now() - start
    html += decoder.decode(value, { stream: true })
  }
  const elapsed = Date.now() - start
  for (const text of ['"'Dashboard', 'Total Revenue', 'Total Invoices', 'Revenue', 'Latest Invoices', 'Loading total revenue', 'Loading total invoices', 'Loading revenue history', 'Loading latest invoices', '12,345', 'Jan', '1,200', 'Acme', '300']) {
    assert.ok(html.includes(text), "'`Missing ${text}`)
  }
  assert.ok(firstChunkAt < 1500, `Shell took ${firstChunkAt}ms`)
  assert.ok(elapsed >= 1900, `Response finished before mock delay: ${elapsed}ms`)
  const calls = readFileSync('"'/tmp/dashboard-fetch-calls.log', 'utf8').trim().split('\\n').length
  assert.equal(calls, request, "'`Expected one API call per request; saw ${calls}`)
  console.log(`Request ${request}: shell in ${firstChunkAt}ms, streamed data in ${elapsed}ms, ${calls} API call(s) total`)
}
EOF'
